\entrytitle{83}{Hash preimages and second preimages}{strengthPolynomial}{evidenceProved}{hardwareExponential}
\setcounter{problem}{82}
\begin{problem}[Hash preimages and second preimages]
Given oracle access to $H:\{0,1\}^{\ell}\to\{0,1\}^n$ and a target $y$ in its image, find $x$ satisfying $H(x)=y$. For second-preimage search, a particular $x_0$ is supplied, $y=H(x_0)$, and the output must satisfy $x\ne x_0$. Assume a random-function model and a search domain large enough to contain suitable preimages. The random-function comparison counts hash-oracle queries; an explicit hash circuit adds quantum gate cost and admits classical bit-complexity bounds.
\end{problem}

\speedupheading
\complexity{Quantum}{$\Theta(\sqrt{D/M})$ queries, Grover search and amplitude amplification.}
Here $M\ge1$ is the number of valid inputs in the domain of size $D=2^\ell$, and success probability is constant. Random $n$-bit outputs give the familiar $\Theta(2^{n/2})$ scale when the marked fraction has order $2^{-n}$. The excluded input in second-preimage search is incorporated in the predicate. Unknown $M$ can be handled by randomized iteration counts. If reversible hashing and checking cost $G$ gates, the gate bound is $O((G+\ell)\sqrt{D/M})$.

\complexity{Classical}{$\Theta(D/M)$ queries, random sampling.}
These bounds match the random-oracle lower bound at constant success probability. For an explicit hash circuit with $G$ gates, the preimage predicate on $\ell$ input bits has $O(\ell+G)$-size Boolean encoding. Tensor contraction gives $\operatorname{poly}(\ell+G)2^{O((\ell+G)/\sqrt{\log(\ell+G)})}$ deterministic search time. When $\ell+G=O(n)$, that explicit-family bound is subexponential in the output length.

\dimensionlabel{Strength}{strengthPolynomial} Tight quadratic polynomial speedup in the oracle search-space ratio, arising from amplitude amplification. In the random-output parameter $n$, the exponent changes from $n$ to $n/2$ without power saving.

\dimensionlabel{Evidence}{evidenceProved} Fully proved for the oracle task with fixed marked fraction. Explicit hash functions are compared using their representation-dependent algorithms as well.

\dimensionlabel{Hardware}{hardwareExponential} The candidate register needs $\ell$ logical qubits plus reversible-hash workspace and the equality test. Full cryptographic searches require exponentially many coherent evaluations and fault tolerance. Parallel search trades elapsed time for independently maintained quantum processors.

{\small [Before ``ETH is false'', the generic preimage comparison used $\Theta(2^n)$ classical versus $\Theta(2^{n/2})$ quantum queries, with the same trial bounds transferred to explicit hash evaluation.]\par}
\subhead{Algorithm}
\begin{algorithmindex}{83}
\item \href{https://arxiv.org/pdf/quant-ph/9605034}{Boyer, Brassard, H\o yer and Tapp, \emph{Tight Bounds on Quantum Searching} (1998)}. Search procedure with an unknown number of marked items and its expected-query analysis.
\item \href{https://arxiv.org/pdf/quant-ph/0005055}{Brassard, H\o yer, Mosca and Tapp, \emph{Quantum Amplitude Amplification and Estimation} (2002)}. Section 2, Theorems 2--3: known and unknown success probabilities.
\item \href{https://github.com/openai/math/blob/main/preprints/The-Exponential-Time-Hypothesis-is-False-October-25-2026/paper.pdf}{OpenAI, \emph{The Exponential Time Hypothesis Is False} (2026)}. Theorem 1.1 and witness self-reduction: search for a satisfying assignment of the explicit Boolean verification circuit.
